"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["53141"],{320466(e){e.exports=JSON.parse('{"id":13882,"title":"location de voiture app mobile","description":"app mobile, location de voiture g\xe9n\xe8re propre contrat, via une inscription de l\'agence dans le formulaire contenant: nom agence, adresse postale, N\xb0Tel Fixe (num\xe9ro), N\xb0Tel Mobile (num\xe9ro),, IF (num\xe9ro), ICE (num\xe9ro), CNSS (num\xe9ro), Patente (num\xe9ro), email,mote de passe, logo, cachet & signature.\\nUne fois l\'inscription est termin\xe9, l\'agence peut se connecter par son email et le mot de passe, une fois se connecter, on peut voir la logo en haut \xe0 gauche et le nom d\'agence en haut centr\xe9, plus un bouton \\"ajouter votre parc\\" qui sert \xe0 ajouter le parc de l\'agence par un formulaire une fois en cliquant sur ce bouton, on trouve \\"Marque, Mod\xe8le, Couleur, Immatriculation, Carburant (Diesel, Essence, Hybride, Electrique), une image g\xe9n\xe8re en IA de la v\xe9hicule qui se base sur la marque, mod\xe8le et la couleur une fois ces trois param\xe8tres sont d\xe9finit, apr\xe8s la cr\xe9ation, le bouton \\"ajouter votre parc\\" est remplac\xe9 par le bouton + et fais la m\xeame fonction.\\nune fois la voiture est cr\xe9e, on peut voir son \xe9tat par \\"Disponible en vert, Occup\xe9 en rouge, et R\xe9server par orange\\".\\nSi la voiture est Disponible, on peut voir dedans, le bouton \\"cr\xe9er contrat\\" et dedans de ce bouton, on peut voir le formulaire n\xe9cessaire pour cr\xe9er le contrat d\'un client (nom & pr\xe9nom, CINE, N\xb0 Permis, Adresse Postale, N\xb0 Tel, 2\xe8me Conducteur s\'il est existe), plus les infos de voiture s\xe9lectionn\xe9, et une checklist de la voiture, et enfin, les infos de l\'agent (nom & pr\xe9nom, N\xb0 Tel, signature num\xe9rique du client).\\nSi la voiture est Occup\xe9, on peut voir deux bouton \\"d\xe9tail\\" & \\"extension\\", si on clique sur \\"d\xe9tail\\", on peut voir les infos du client qui a lou\xe9 la voiture (nom & pr\xe9nom, N\xb0 Tel), et si je clique sur \\"extension\\", je peux voir \\"date de retour\\", si le client veut faire une extension.\\nSi je clique sur \\"R\xe9server\\", je peux voir le formulaire:  \\"nom & pr\xe9nom\\", \\"date de d\xe9part \\" & \\"date de retour\\".\\nLe contrat sera fait sous format PDF et t\xe9l\xe9chargeable.\\n","owner":"boutat6","upvotes":1,"downvotes":0,"upvoteDifference":1,"updatedAt":"2026-06-16T00:37:31.323Z"}')}}]);